func testFluxoToManyAddOpFluDocumentoVendas(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Fluxo
	var b, c, d, e DocumentoVenda

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, fluxoDBTypes, false, strmangle.SetComplement(fluxoPrimaryKeyColumns, fluxoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*DocumentoVenda{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, documentoVendaDBTypes, false, strmangle.SetComplement(documentoVendaPrimaryKeyColumns, documentoVendaColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*DocumentoVenda{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddFluDocumentoVendas(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.FluID != first.FluID {
			t.Error("foreign key was wrong value", a.FluID, first.FluID)
		}
		if a.FluID != second.FluID {
			t.Error("foreign key was wrong value", a.FluID, second.FluID)
		}

		if first.R.Flu != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Flu != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.FluDocumentoVendas[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.FluDocumentoVendas[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.FluDocumentoVendas().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
